import os
try:
    import requests
except ImportError as e:
    raise ImportError("The 'requests' package is required for the Strands LiteLLM proxy setup. Install with: pip install requests") from e

"""
Strands model setup for using a LiteLLM proxy on localhost:4000.

Environment variables:
  STRANDS_PROXY_BASE_URL  - base URL of the LiteLLM proxy (default: http://localhost:4000)
  STRANDS_MODEL           - model name to pass to the proxy (default: lite-llm)
"""

# Defaults (can be overridden by env vars)
BASE_URL = os.environ.get("STRANDS_PROXY_BASE_URL", "http://localhost:4000")
MODEL_NAME = os.environ.get("STRANDS_MODEL", "lite-llm")

def _parse_response(json_resp):
    if not isinstance(json_resp, dict):
        return None
    # Common shapes
    if "choices" in json_resp and isinstance(json_resp["choices"], list) and json_resp["choices"]:
        c = json_resp["choices"][0]
        # OpenAI-like
        if isinstance(c, dict) and "message" in c and isinstance(c["message"], dict):
            text = c["message"].get("content")
            if text is not None:
                return text
        # plain text in choices
        if isinstance(c, dict) and "text" in c:
            return c["text"]
        # fallback
        text = json_resp["choices"][0].get("text")
        if text:
            return text
    if "text" in json_resp:
        return json_resp["text"]
    return None

def _call_proxy(prompt: str, model: str, base_url: str = BASE_URL) -> str:
    # Try a chat-completions style endpoint first
    chat_url = f"{base_url.rstrip('/')}/v1/chat/completions"
    chat_payload = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}]
    }
    try:
        r = requests.post(chat_url, json=chat_payload, timeout=60)
        if r.status_code == 200:
            resp = r.json()
            text = _parse_response(resp)
            if text:
                return text
    except Exception:
        pass  # fall through to generator endpoint

    # Fallback to a generic generate endpoint
    gen_url = f"{base_url.rstrip('/')}/v1/generate"
    gen_payload = {
        "model": model,
        "prompt": prompt
    }
    try:
        r = requests.post(gen_url, json=gen_payload, timeout=60)
        if r.status_code == 200:
            resp = r.json()
            text = _parse_response(resp)
            if text:
                return text
    except Exception:
        pass

    # As a last resort, try a very simple GET-based heuristic (if proxy supports it)
    try:
        status_url = f"{base_url.rstrip('/')}/health"
        r = requests.get(status_url, timeout=5)
        if r.status_code == 200:
            raise RuntimeError("Proxy is reachable but did not return a valid completion.")
    except Exception:
        pass

    raise RuntimeError(f"LiteLLM proxy failed to generate a response for model '{model}' at '{base_url}' with prompt: {prompt!r}")

class StrandsModel:
    def __init__(self, base_url: str = BASE_URL, model_name: str = MODEL_NAME):
        self.base_url = base_url.rstrip("/")
        self.model_name = model_name

    def generate(self, prompt: str, **kwargs) -> str:
        """
        Generate a completion for the given prompt using the LiteLLM proxy.

        Additional kwargs are accepted for compatibility but are not guaranteed to be used
        by the proxy. Pass through any relevant options as part of prompt if needed.
        """
        return _call_proxy(prompt, self.model_name, self.base_url)

def get_strands_model(base_url: str = None, model_name: str = None) -> StrandsModel:
    """
    Factory to obtain a StrandsModel instance configured to talk to the LiteLLM proxy.

    - base_url: optional override for the proxy base URL
    - model_name: optional override for the model name passed to the proxy
    """
    return StrandsModel(
        base_url=base_url or BASE_URL,
        model_name=model_name or MODEL_NAME
    )

__all__ = ["StrandsModel", "get_strands_model"]

import requests
from typing import List, Dict, Optional, Any

class LiteLLMClient:
    """
    Client to talk to the LiteLLM proxy running on localhost:4000.
    Assumes the proxy implements a OpenAI-like chat-completions API at
    /v1/chat/completions.
    """
    def __init__(self, url: str = "http://localhost:4000/v1/chat/completions"):
        self.url = url
        self.session = requests.Session()

    def chat(
        self,
        messages: List[Dict[str, str]],
        model: Optional[str] = None,
        temperature: float = 0.0,
        max_tokens: Optional[int] = None
    ) -> str:
        payload: Dict[str, Any] = {
            "messages": messages,
            "model": model or "lite-llm",
            "temperature": temperature,
        }
        if max_tokens is not None:
            payload["max_tokens"] = max_tokens

        resp = self.session.post(self.url, json=payload, timeout=60)
        resp.raise_for_status()
        data = resp.json()
        try:
            return data["choices"][0]["message"]["content"]
        except (KeyError, IndexError) as e:
            raise RuntimeError(f"Invalid response from LiteLLM proxy: {data}") from e

class StrandsLiteLLMModel:
    """
    Lightweight adapter to present a Strands-friendly interface that uses
    the LiteLLM proxy behind localhost:4000.

    Usage pattern (depending on your Strands integration in the repo):
      llm = build_strands_model(system_prompt="You are an AWS assistant.")
      response = llm.generate(prompt="Explain how S3 versioning works.", history=history)
    """
    def __init__(self, system_prompt: Optional[str] = None, proxy_url: str = "http://localhost:4000/v1/chat/completions"):
        self.client = LiteLLMClient(url=proxy_url)
        self.system_prompt = system_prompt

    def generate(
        self,
        prompt: str,
        history: Optional[List[List[Dict[str, str]]]] = None,
        **kwargs
    ) -> str:
        messages: List[Dict[str, str]] = []
        if self.system_prompt:
            messages.append({"role": "system", "content": self.system_prompt})

        if history:
            # Flatten a history of messages (depending on how Strands stores history)
            for turn in history:
                for msg in turn:
                    messages.append(msg)

        messages.append({"role": "user", "content": prompt})
        return self.client.chat(messages, **kwargs)

def build_strands_model(system_prompt: Optional[str] = None, proxy_url: str = "http://localhost:4000/v1/chat/completions") -> StrandsLiteLLMModel:
    """
    Factory to create a Strands-compatible model instance that uses the LiteLLM proxy.
    """
    return StrandsLiteLLMModel(system_prompt=system_prompt, proxy_url=proxy_url)

