import json
import urllib.request
import urllib.error
import argparse

def check_model_gateway(host="localhost", port=8000, path="/health", timeout=5.0):
    url = f"http://{host}:{port}{path}"
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            status = resp.getcode()
            return {"reachable": True, "status_code": status}
    except urllib.error.HTTPError as http_err:
        return {"reachable": False, "status_code": http_err.code, "error": http_err.reason}
    except urllib.error.URLError as url_err:
        reason = getattr(url_err, "reason", None)
        msg = str(reason) if reason is not None else str(url_err)
        return {"reachable": False, "error": msg}
    except Exception as exc:
        return {"reachable": False, "error": str(exc)}

def main():
    parser = argparse.ArgumentParser(description="Health check for local model gateway")
    parser.add_argument("--host", default="localhost", help="Gateway host")
    parser.add_argument("--port", type=int, default=8000, help="Gateway port")
    parser.add_argument("--path", default="/health", help="Health check path")
    parser.add_argument("--timeout", type=float, default=5.0, help="Request timeout seconds")
    args = parser.parse_args()

    result = check_model_gateway(args.host, args.port, args.path, args.timeout)
    print(json.dumps(result))

if __name__ == "__main__":
    main()

import os
import json
import urllib.request
import urllib.error

def check_gateway_url(url: str, timeout: float = 2.0) -> dict:
    result = {
        "reachable": False,
        "http_status": None,
        "error": None,
        "details": None
    }
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            code = resp.getcode()
            result["http_status"] = code
            if 200 <= code < 300:
                data = resp.read(4096).decode(errors="ignore")
                # Try to parse JSON and look for a status field
                try:
                    payload = json.loads(data)
                    if isinstance(payload, dict) and "status" in payload:
                        stat = str(payload["status"]).lower()
                        if stat in ("ok", "healthy", "healthy_status", "running"):
                            result["reachable"] = True
                            result["details"] = payload
                            return result
                except Exception:
                    pass
                # If no explicit health indicator, 2xx is considered reachable
                result["reachable"] = True
                if data:
                    result["details"] = {"raw": data}
                return result
            else:
                result["error"] = f"HTTP status {code}"
                return result
    except urllib.error.HTTPError as e:
        result["http_status"] = getattr(e, "code", None)
        result["error"] = str(e)
        return result
    except urllib.error.URLError as e:
        result["error"] = str(e.reason if hasattr(e, "reason") else e)
        return result
    except Exception as e:
        result["error"] = str(e)
        return result

def main():
    # Config via environment variables with sensible defaults
    host = os.environ.get("GATEWAY_HOST", "localhost")
    port = os.environ.get("GATEWAY_PORT", "8000")
    path = os.environ.get("GATEWAY_HEALTH_PATH", "/health")
    scheme = os.environ.get("GATEWAY_SCHEME", "http")
    health_url = os.environ.get("GATEWAY_HEALTH_URL")
    timeout = float(os.environ.get("GATEWAY_TIMEOUT", "2"))

    if health_url:
        url = health_url
    else:
        if not path.startswith("/"):
            path = "/" + path
        url = f"{scheme}://{host}:{port}{path}"

    result = check_gateway_url(url, timeout=timeout)
    print(json.dumps(result))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Python health check for the local model gateway.
Returns a JSON payload indicating whether the gateway is reachable.
"""

import argparse
import json
import time
import urllib.error
import urllib.request


def check_gateway_health(url: str = "http://localhost:8000/health", timeout: float = 2.0) -> dict:
    result = {
        "reachable": False,
        "status_code": None,
        "duration_ms": None,
        "detail": "",
    }

    start = time.time()
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            duration = int((time.time() - start) * 1000)
            result["duration_ms"] = duration
            result["status_code"] = resp.getcode()

            if 200 <= resp.getcode() < 400:
                result["reachable"] = True
                # Attempt to derive a health signal from the body if present
                try:
                    body = resp.read().decode("utf-8", errors="ignore")
                    if body:
                        try:
                            j = json.loads(body)
                            health_tag = None
                            if isinstance(j, dict):
                                for key in ("status", "health", "ready"):
                                    if key in j:
                                        val = str(j[key]).lower()
                                        if val in ("ok", "healthy", "up", "ready", "true"):
                                            health_tag = True
                                            break
                            if health_tag:
                                result["detail"] = "gateway reported healthy in body"
                                return result
                        except json.JSONDecodeError:
                            pass
                    result["detail"] = "gateway responded 2xx; no clear in-body health indicator"
                except Exception as e:
                    result["detail"] = f"error reading body: {e}"
                return result
            else:
                result["detail"] = f"HTTP status {result['status_code']}"
                return result

    except urllib.error.URLError as e:
        result["duration_ms"] = int((time.time() - start) * 1000)
        result["detail"] = f"URL error: {e}"
        return result
    except Exception as e:
        result["duration_ms"] = int((time.time() - start) * 1000)
        result["detail"] = f"unexpected error: {e}"
        return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Check if the local model gateway is reachable.")
    parser.add_argument("--url", default="http://localhost:8000/health", help="Health endpoint to probe")
    parser.add_argument("--timeout", type=float, default=2.0, help="Request timeout in seconds")
    args = parser.parse_args()

    res = check_gateway_health(args.url, timeout=args.timeout)
    print(json.dumps(res))

