from typing import Optional, Any
import time
import os


def _confirm_landed(s3_client, bucket: str, key: str, timeout: float = 60.0, poll_interval: float = 1.0) -> Any:
    """
    Polls S3 until the object exists (HEAD succeeds) or timeout.
    Returns the head_object response when found.
    Raises TimeoutError if not landed within timeout.
    """
    end_time = time.time() + timeout
    from botocore.exceptions import ClientError
    while True:
        try:
            return s3_client.head_object(Bucket=bucket, Key=key)
        except ClientError as e:
            error_code = e.response.get('Error', {}).get('Code')
            if error_code not in ('404', 'NoSuchKey', 'NotFound'):
                # Unexpected error; re-raise
                raise
        if time.time() >= end_time:
            raise TimeoutError(f"Object s3://{bucket}/{key} did not land within {timeout} seconds")
        time.sleep(poll_interval)


def upload_file_and_confirm(bucket: str, key: str, filepath: str, s3_client: Optional[object] = None,
                          timeout: float = 60.0, poll_interval: float = 1.0) -> Any:
    """
    Upload a file to S3 and confirm it landed by polling HEAD until object exists.
    Returns the head_object response when landed.
    """
    if s3_client is None:
        import boto3
        s3_client = boto3.client('s3')
    if not os.path.isfile(filepath):
        raise FileNotFoundError(filepath)
    s3_client.upload_file(filepath, bucket, key)
    return _confirm_landed(s3_client, bucket, key, timeout=timeout, poll_interval=poll_interval)


