import time
from typing import Optional, Dict, Any
import boto3
from botocore.exceptions import ClientError

def _get_s3_client(s3_client: Optional[object] = None):
    return s3_client or boto3.client('s3')

def confirm_s3_object(bucket: str, key: str, s3_client: Optional[object] = None, max_retries: int = 5, delay: float = 0.0) -> bool:
    """
    Confirm that an object exists in S3 by polling head_object.
    Returns True if found within retries, otherwise False.
    """
    client = _get_s3_client(s3_client)
    for attempt in range(max_retries):
        try:
            client.head_object(Bucket=bucket, Key=key)
            return True
        except ClientError as e:
            code = e.response.get('Error', {}).get('Code')
            # Treat common not-found codes as not exists
            if code in ('404', 'NotFound', 'NoSuchKey'):
                if attempt == max_retries - 1:
                    return False
                if delay:
                    time.sleep(delay)
                continue
            else:
                # Re-raise unexpected errors
                raise
    return False

def upload_file_with_confirm(local_path: str, bucket: str, key: str, s3_client: Optional[object] = None, extra_args: Optional[Dict[str, Any]] = None, max_retries: int = 5, delay: float = 0.0) -> bool:
    """
    Upload a local file to S3 and confirm it landed.
    Returns True if the object exists after upload.
    """
    client = _get_s3_client(s3_client)
    # Perform upload
    if extra_args:
        client.upload_file(local_path, bucket, key, ExtraArgs=extra_args)
    else:
        client.upload_file(local_path, bucket, key)

    # Confirm landing
    return confirm_s3_object(bucket, key, s3_client=client, max_retries=max_retries, delay=delay)

