import time
from typing import Optional
import boto3
from botocore.exceptions import ClientError


def _is_not_found_error(e: ClientError) -> bool:
    code = None
    try:
        code = e.response.get('Error', {}).get('Code')
    except Exception:
        code = None
    return code in ('404', 'NotFound', 'NoSuchKey')


def confirm_object_landed(
    bucket: str,
    key: str,
    s3_client: Optional[object] = None,
    timeout: float = 60.0,
    interval: float = 2.0,
) -> bool:
    if s3_client is None:
        s3_client = boto3.client('s3')

    start = time.time()
    while True:
        try:
            s3_client.head_object(Bucket=bucket, Key=key)
            return True
        except ClientError as e:
            if _is_not_found_error(e):
                elapsed = time.time() - start
                if elapsed >= timeout:
                    return False
                time.sleep(interval)
                continue
            else:
                raise
        except Exception:
            raise


def upload_file_and_confirm(
    bucket: str,
    key: str,
    file_path: str,
    s3_client: Optional[object] = None,
    timeout: float = 60.0,
    interval: float = 2.0,
) -> bool:
    if s3_client is None:
        s3_client = boto3.client('s3')

    s3_client.upload_file(Filename=file_path, Bucket=bucket, Key=key)
    return confirm_object_landed(
        bucket, key, s3_client=s3_client, timeout=timeout, interval=interval
    )


